as color.","alternatives":[{"id":"01a218eb-555c-7f81-9d0f-57981158ad58","description":"Red","correct_answer":true},{"id":"01a218eb-555c-72bb-b2a4-689c75d4cef0","description":"Orange","correct_answer":false},{"id":"01a218eb-555c-75e8-baa5-2a35f7bb89d1","description":"Blue","correct_answer":false},{"id":"01a218eb-555c-7c8e-b0d1-a9f25f67f852","description":"Purple","correct_answer":false}]},{"id":"01a218eb-555c-749c-8c39-620528bff63b","locale":"en-US","category":"01a21312-b489-7dd6-93ca-116c8464996a","question":"Totems are most commonly associated with which of the following?","difficulty":1,"explanation":"Totems are associated with Indigenous cultures, though traditions vary widely among Indigenous peoples; some Northwest Coast peoples, for example, carve totem poles linked to family histories.","alternatives":[{"id":"01a218eb-555c-7263-a1d8-a3c3e4a9e90e","description":"Indigenous cultures","correct_answer":true},{"id":"01a218eb-555c-7662-93b9-1d48c2b6017a","description":"Modern corporations","correct_answer":false},{"id":"01a218eb-555c-7483-8685-7069e3249927","description":"Ancient Greek city-states","correct_answer":false},{"id":"01a218eb-555c-77ff-864b-497596b35e50","description":"Medieval European guilds","correct_answer":false}]},{"id":"01a218eb-555c-707c-ba59-46c8e7205a68","locale":"en-US","category":"01a21312-b489-7dd6-93ca-116c8464996a","question":"What is the traditional color associated with St. Patrick\'s Day?","difficulty":1,"explanation":"Green is linked to the shamrock and Ireland\u2019s nickname, the Emerald Isle. Wearing it is a popular St. Patrick\u2019s Day custom.","alternatives":[{"id":"01a218eb-555c-7273-9835-5acb936db2de","description":"Green","correct_answer":true},{"id":"01a218eb-555c-71a8-b180-c71ecb927f0a","description":"Blue","correct_answer":false},{"id":"01a218eb-555c-7f30-b359-4de396c1f2f3","description":"Red","correct_answer":false},{"id":"01a218eb-555c-7812-b3cc-e4270775db9a","description":"Yellow","correct_answer":false}]},{"id":"01a21